def populate_case_workflow_records(apps, schema_editor):
    DSRRequest = apps.get_model("dsr", "DSRRequest")
    DSRDeadlinePolicy = apps.get_model("dsr", "DSRDeadlinePolicy")
    DSRCaseDisposition = apps.get_model("dsr", "DSRCaseDisposition")
    DSRCaseEscalation = apps.get_model("dsr", "DSRCaseEscalation")
    DSRAuditLog = apps.get_model("dsr", "DSRAuditLog")
    DSRResponsePublication = apps.get_model("dsr", "DSRResponsePublication")

    policies = {}
    for policy in DSRDeadlinePolicy.objects.order_by(
        "jurisdiction_code", "request_type", "-version"
    ):
        policies.setdefault((policy.jurisdiction_code, policy.request_type), policy)

    for dsr in DSRRequest.objects.all().iterator():
        policy = policies.get((dsr.jurisdiction_code, dsr.request_type))
        if policy is not None:
            DSRRequest.objects.filter(pk=dsr.pk).update(deadline_policy_id=policy.pk)

        audit = DSRAuditLog.objects.filter(dsr_id=dsr.pk).order_by("-timestamp").first()
        if dsr.state in {"CLOSED", "REJECTED", "WITHDRAWN"}:
            publication = (
                DSRResponsePublication.objects.filter(
                    response_version__dsr_id=dsr.pk
                ).order_by("-published_at").first()
            )
            is_withdrawn = dsr.state == "WITHDRAWN" or dsr.resolution_status == "WITHDRAWN"
            DSRCaseDisposition.objects.get_or_create(
                dsr_id=dsr.pk,
                defaults={
                    "outcome": dsr.resolution_status,
                    "initiated_by": "PATIENT" if is_withdrawn else "ORGANIZATION",
                    "actor_id": audit.actor_id if audit else "system-migration",
                    "reason": audit.reason if audit else "",
                    "communicated_at": publication.published_at if publication else None,
                },
            )
        if dsr.state == "ESCALATED":
            DSRCaseEscalation.objects.get_or_create(
                dsr_id=dsr.pk,
                resolved_at__isnull=True,
                defaults={
                    "reason": audit.reason if audit else "Migrated active escalation",
                    "opened_by": audit.actor_id if audit else "system-migration",
                    "assigned_to": dsr.assigned_to,
                },
            )


